import{_ as t,o as e,c as l,a4 as p}from"./chunks/framework.DzJZdBQK.js";const b=JSON.parse('{"title":"写作课作业-060","description":"","frontmatter":{"date":"2020-09-17T22:31:03","title":"写作课作业-060","categories":["写作","作业"],"tags":["写作","作业"]},"headers":[],"relativePath":"posts/homework/060.md","filePath":"posts/homework/060.md"}'),u={name:"posts/homework/060.md"};function c(a,o,k,s,i,r){return e(),l("div",null,[...o[0]||(o[0]=[p("<blockquote><p>9.17写作作业：写一句自己想说的话，罗列出能够表达相同意思的句子，尽可能穷尽其说法。[微笑]</p></blockquote><p>对未知保持敬畏，对已知保持疑问。</p><ul><li>对已知保持疑问是要及时更新自己的知识，曾经的正确可能已经是错误的。</li></ul><blockquote><p>太阳系有9大行星么？然而，从2006年8月24日起，太阳系只有8大行星，即：水星、金星、地球、火星、木星、土星、天王星和海王星。冥王星被划为矮行星，并命名为小行星134340号，已经从太阳系九大行星中被除名了。</p></blockquote><blockquote><p>珠穆朗玛峰的高度是8848米？然而，中国采用的是2005年中国国家测绘局测量的岩面高（裸高即地质高度）为8844.43米。</p></blockquote><blockquote><p>天空为什么是蓝色？那是因为“空气中会有许多微小的尘埃、水滴、冰晶等物质，当太阳光通过空气时，波长较短的蓝、紫、靛等色光，很容易被悬浮在空气中的微粒阻挡，从而使光线散射向四方，使天空呈现出蔚蓝色。”，然而，天空蓝色之起因是：“空气中有不可消除的‘杂质’，即空气自身的涨落。密度涨落等对阳光的散射，形成了蓝天。”</p></blockquote><ul><li>对未知保持敬畏是要有科学的方法，不断的排出未知原因。</li></ul><blockquote><p>1862年，巴斯德设计鹅颈瓶，证明空气中有细菌。当年巴斯德制作的几个鹅颈瓶，现在还放在巴黎的巴斯德研究院里公开展示。这些瓶子已经放置了一百五十多年，里面的肉汁依然清亮。</p></blockquote><blockquote><p>科赫研究炭疽杆菌，不断的对自己发问，提出是否有其他可能，修改实验方法。</p></blockquote><ul><li>对未知保持敬畏不是迷信。</li></ul><blockquote><p>三体</p><p>有神论</p></blockquote><ul><li>对已知保持疑问就是要突破思维局限</li></ul><blockquote><p>维萨里用实证解剖，修正了统御了千年的盖伦学说。</p></blockquote><ul><li>对未知保持敬畏，对已知保持疑问是不要轻易下结论，避免先入为主。</li></ul><blockquote><p>王坚博士的云计算，之前被很多人说成“骗子”项目。</p></blockquote><blockquote><p>现在市场上对AI就很随意，不论什么都往AI上靠。上个篮球课，加个可穿戴设备就是AI了。</p></blockquote>",16)])])}const q=t(u,[["render",c]]);export{b as __pageData,q as default};
